// SPDX-License-Identifier: MPL-2.0
//
// GitRemoteTrustSeamTests — offline, synthetic contract suite for the
// Android platform-trust seam (lane job-f74b2a485e9a4434). Nothing here
// opens a socket, reads the real platform trust store, touches a
// credential, or requires a device: the fixtures are the two public
// SYNTHETIC self-signed test roots below (CN=Floe Synthetic Test Root
// A/B, O=FloeTests, OU=invalid — generated by openssl for this suite and
// stored beside the lane evidence), and every assertion is deterministic
// on any host. The suite locks: bundle verification (ownership, bounds,
// digest, PEM count, symlink escape), install/retire binding lifecycle,
// per-operation re-verification of a changed file, the fail-closed
// decision table (unbound/changed/rejected), the credential-callback
// URL scope, the pinned no-offsite-redirect constant, and the FloeError
// mapping — while LocalGitServiceTests keeps proving that OFFLINE Git
// (init/stage/commit/diff/branch) needs no trust at all.

import Foundation
import Testing
import Crypto
import FloeCore
import libgit2
@testable import FloeGit

