private func hexDigest(_ data: Data) -> String {
    SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
}

private func makePrivateRoot(_ name: String = "floe-git-trust-tests") throws -> URL {
    let root = FileManager.default.temporaryDirectory
        .appendingPathComponent("\(name)-\(UUID().uuidString)", isDirectory: true)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    return root
}

/// Writes `bytes` at root/platform-trust-bundle.pem and builds a record
/// describing EXACTLY those bytes unless an expectation is overridden
/// (that is how the mismatch cases are constructed).
private func makeRecord(
    inRoot root: URL,
    bytes: Data,
    certificates: Int? = nil,
    byteCount: Int? = nil,
    digest: String? = nil,
    bundleID: String = "gtb-test-fixture",
    fileLeaf: String? = nil,
    at url: URL? = nil
) throws -> GitTrustedBundleRecord {
    let fileURL = url ?? root.appendingPathComponent(fileLeaf ?? GitRemoteTrust.bundleFileName)
    try bytes.write(to: fileURL)
    return GitTrustedBundleRecord(
        bundleID: bundleID,
        bundleFileURL: fileURL,
        privateRootPath: root.path,
        expectedSHA256Hex: digest ?? hexDigest(bytes),
        expectedCertificateCount: certificates ?? 2,
        expectedByteCount: byteCount ?? bytes.count,
        exportedAtUnixMillis: 1_793_000_000_000
    )
}

private func twoCertBundleBytes() -> Data {
    (floeTestRootA + "\n" + floeTestRootB + "\n").data(using: .ascii)!
}

@Suite("GitRemoteTrust bundle verification")
struct GitRemoteTrustVerificationTests {
    @Test("a matching synthetic bundle verifies and reports its resolved path inside the root")
    func happyPath() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let record = try makeRecord(inRoot: root, bytes: twoCertBundleBytes())
        let resolved = try GitRemoteTrust.verify(record)
        #expect(resolved.hasPrefix(root.resolvingSymlinksInPath().path + "/"))
        #expect(resolved.hasSuffix(GitRemoteTrust.bundleFileName))
    }

    @Test("deterministic derivation: the same bytes under a different root produce the same digest and verify")
    func deterministicAcrossRoots() throws {
        let bytes = twoCertBundleBytes()
        let digest = hexDigest(bytes)
        let rootOne = try makePrivateRoot("root-one")
        let rootTwo = try makePrivateRoot("root-two")
        defer {
            try? FileManager.default.removeItem(at: rootOne)
            try? FileManager.default.removeItem(at: rootTwo)
        }
        let first = try makeRecord(inRoot: rootOne, bytes: bytes)
        let second = try makeRecord(inRoot: rootTwo, bytes: bytes, bundleID: "gtb-test-fixture-2")
        #expect(first.expectedSHA256Hex == digest)
        #expect(second.expectedSHA256Hex == digest)
        _ = try GitRemoteTrust.verify(first)
        _ = try GitRemoteTrust.verify(second)
    }

    @Test("digest mismatch fails closed")
    func digestMismatch() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let tampered = floeTestRootB.data(using: .ascii)!
        let record = try makeRecord(
            inRoot: root,
            bytes: tampered,
            certificates: 1,
            digest: hexDigest(twoCertBundleBytes())
        )
        #expect(throws: GitRemoteTrustError.digestMismatch(
            expected: record.expectedSHA256Hex,
            observed: hexDigest(tampered)
        )) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("byte-count mismatch is caught before the digest")
    func byteCountMismatch() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let record = try makeRecord(inRoot: root, bytes: twoCertBundleBytes(), byteCount: 42)
        #expect(throws: GitRemoteTrustError.byteCountMismatch(
            expected: 42,
            observed: twoCertBundleBytes().count
        )) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("declared certificate count must equal the observed PEM blocks")
    func certificateCountMismatch() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let record = try makeRecord(inRoot: root, bytes: twoCertBundleBytes(), certificates: 3)
        #expect(throws: GitRemoteTrustError.certificateCountMismatch(declared: 3, observed: 2)) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("unbalanced PEM blocks are rejected as malformed")
    func malformedPEM() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let bytes = (floeTestRootA + "\n" + "-----BEGIN CERTIFICATE-----\n").data(using: .ascii)!
        let record = try makeRecord(
            inRoot: root,
            bytes: bytes,
            certificates: 1,
            byteCount: bytes.count
        )
        do {
            _ = try GitRemoteTrust.verify(record)
            Issue.record("malformed bundle unexpectedly verified")
        } catch let error as GitRemoteTrustError {
            guard case .malformedBundlePEM = error else {
                Issue.record("unexpected trust error: \(error)")
                return
            }
        }
    }

    @Test("a bundle above the hard size bound fails closed during the bounded read")
    func oversizedBundle() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        var bytes = twoCertBundleBytes()
        bytes.append(Data(count: GitRemoteTrust.bundleLimitBytes))
        let record = try makeRecord(
            inRoot: root,
            bytes: bytes,
            byteCount: twoCertBundleBytes().count
        )
        #expect(throws: GitRemoteTrustError.bundleTooLarge(limitBytes: GitRemoteTrust.bundleLimitBytes)) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("a path outside the app-private root is rejected")
    func pathOutsideRoot() throws {
        let inside = try makePrivateRoot("inside")
        let outside = try makePrivateRoot("outside")
        defer {
            try? FileManager.default.removeItem(at: inside)
            try? FileManager.default.removeItem(at: outside)
        }
        let bytes = twoCertBundleBytes()
        let record = try makeRecord(
            inRoot: inside,
            bytes: bytes,
            at: outside.appendingPathComponent(GitRemoteTrust.bundleFileName)
        )
        // Note the file was written under `outside` while the record still
        // declares `inside` as its root.
        #expect(throws: GitRemoteTrustError.bundlePathOutsidePrivateRoot) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("a symlink escaping the private root is rejected before the file is opened")
    func symlinkEscape() throws {
        let root = try makePrivateRoot()
        let elsewhere = try makePrivateRoot("elsewhere")
        defer {
            try? FileManager.default.removeItem(at: root)
            try? FileManager.default.removeItem(at: elsewhere)
        }
        let bytes = twoCertBundleBytes()
        let realURL = elsewhere.appendingPathComponent(GitRemoteTrust.bundleFileName)
        try bytes.write(to: realURL)
        let linkURL = root.appendingPathComponent(GitRemoteTrust.bundleFileName)
        try FileManager.default.createSymbolicLink(at: linkURL, withDestinationURL: realURL)
        let record = GitTrustedBundleRecord(
            bundleID: "gtb-symlink",
            bundleFileURL: linkURL,
            privateRootPath: root.path,
            expectedSHA256Hex: hexDigest(bytes),
            expectedCertificateCount: 2,
            expectedByteCount: bytes.count,
            exportedAtUnixMillis: 0
        )
        #expect(throws: GitRemoteTrustError.bundlePathOutsidePrivateRoot) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("wrong leaf name is rejected (single-name contract with the Kotlin adapter)")
    func leafNameMismatch() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let bytes = twoCertBundleBytes()
        let record = try makeRecord(inRoot: root, bytes: bytes, fileLeaf: "other-name.pem")
        #expect(throws: GitRemoteTrustError.bundleLeafNameMismatch(
            expected: GitRemoteTrust.bundleFileName,
            observed: "other-name.pem"
        )) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("a directory where the bundle file must be is rejected")
    func directoryNotFile() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root.appendingPathComponent(GitRemoteTrust.bundleFileName),
            withIntermediateDirectories: true
        )
        let record = GitTrustedBundleRecord(
            bundleID: "gtb-dir",
            bundleFileURL: root.appendingPathComponent(GitRemoteTrust.bundleFileName),
            privateRootPath: root.path,
            expectedSHA256Hex: hexDigest(twoCertBundleBytes()),
            expectedCertificateCount: 2,
            expectedByteCount: twoCertBundleBytes().count,
            exportedAtUnixMillis: 0
        )
        #expect(throws: GitRemoteTrustError.bundleNotARegularFile) {
            _ = try GitRemoteTrust.verify(record)
        }
    }

    @Test("descriptor form is validated before any file access")
    func invalidRecordForms() throws {
        let root = try makePrivateRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let bytes = twoCertBundleBytes()
        let valid = hexDigest(bytes)

        let badDigest = GitTrustedBundleRecord(
            bundleID: "x", bundleFileURL: root.appendingPathComponent(GitRemoteTrust.bundleFileName),
            privateRootPath: root.path, expectedSHA256Hex: String(repeating: "Z", count: 64),
            expectedCertificateCount: 2, expectedByteCount: bytes.count, exportedAtUnixMillis: 0
        )
        #expect(throws: GitRemoteTrustError.invalidRecord(reason: "digest must be 64 lowercase hex characters")) {
            _ = try GitRemoteTrust.verify(badDigest)
        }

        let zeroCerts = GitTrustedBundleRecord(
            bundleID: "x", bundleFileURL: root.appendingPathComponent(GitRemoteTrust.bundleFileName),
            privateRootPath: root.path, expectedSHA256Hex: valid,
            expectedCertificateCount: 0, expectedByteCount: bytes.count, exportedAtUnixMillis: 0
        )
        #expect(throws: GitRemoteTrustError.invalidRecord(reason: "certificate count outside supported bounds")) {
            _ = try GitRemoteTrust.verify(zeroCerts)
        }

        let emptyID = GitTrustedBundleRecord(
            bundleID: "", bundleFileURL: root.appendingPathComponent(GitRemoteTrust.bundleFileName),
            privateRootPath: root.path, expectedSHA256Hex: valid,
            expectedCertificateCount: 2, expectedByteCount: bytes.count, exportedAtUnixMillis: 0
        )
        #expect(throws: GitRemoteTrustError.invalidRecord(reason: "bundle id is empty")) {
            _ = try GitRemoteTrust.verify(emptyID)
        }
    }

    @Test("the cross-language contract constants are pinned")
    func contractConstants() {
        #expect(GitRemoteTrust.bundleFileName == "platform-trust-bundle.pem")
        #expect(GitRemoteTrust.bundleLimitBytes == 4 * 1024 * 1024)
        #expect(GitRemoteTrust.certificateLimitCount == 4096)
    }
}

@Suite("GitRemoteTrust binding lifecycle")
struct GitRemoteTrustBindingTests {
    @Test("install verifies then binds; retire clears with an identity guard")
    func installRetireCycle() throws {
        let trust = GitRemoteTrust()
        let root = try makePrivateRoot("cycle")
        defer { try? FileManager.default.removeItem(at: root) }
        let bytes = twoCertBundleBytes()
        let first = try makeRecord(inRoot: root, bytes: bytes, bundleID: "gtb-1")

        #expect(trust.currentBundleRecord == nil)
        let bound = try trust.install(first)
        #expect(bound == first)
        #expect(trust.currentBundleRecord == first)

        // Re-installing the SAME identity is an idempotent re-verify.
        _ = try trust.install(first)

        // A DIFFERENT identity requires an explicit retire first.
        let otherRoot = try makePrivateRoot("cycle-other")
        defer { try? FileManager.default.removeItem(at: otherRoot) }
        let second = try makeRecord(inRoot: otherRoot, bytes: bytes, bundleID: "gtb-2")
        #expect(throws: GitRemoteTrustError.replacementRequiresRetire(activeBundleID: "gtb-1")) {
            _ = try trust.install(second)
        }

        // Retire under the wrong identity cannot unbind the current record.
        #expect(throws: GitRemoteTrustError.recordIdentityMismatch(
            expectedBundleID: "gtb-nope",
            activeBundleID: "gtb-1"
        )) {
            _ = try trust.retire(expectedBundleID: "gtb-nope")
        }

        #expect(try trust.retire(expectedBundleID: "gtb-1"))
        #expect(trust.currentBundleRecord == nil)
        #expect(try !trust.retire(expectedBundleID: "gtb-1"))
        _ = try trust.install(second)
        #expect(trust.currentBundleRecord == second)
    }

    @Test("a bundle that changed after install revokes the next operation fail-closed")
    func changedFileRevokesPerOperation() throws {
        let trust = GitRemoteTrust()
        let root = try makePrivateRoot("revoked")
        defer { try? FileManager.default.removeItem(at: root) }
        let bytes = twoCertBundleBytes()
        let record = try makeRecord(inRoot: root, bytes: bytes, bundleID: "gtb-change")
        _ = try trust.install(record)

        // Tamper after binding (simulates any change to the published
        // file). The per-operation enforcement path re-verifies, so the
        // NEXT remote operation must fail closed with the typed mismatch
        // before the backend is reached. On Android, prepareRemoteOperation
        // additionally revokes the binding for everything that follows;
        // that wiring is exercised by prepareRemoteOperationPlatformBranch
        // when this suite runs in the Android cohort.
        try floeTestRootA.data(using: .ascii)!.write(
            to: root.appendingPathComponent(GitRemoteTrust.bundleFileName)
        )
        do {
            try GitRemoteTrust.enforceRemoteTrust(
                bindingProvider: { trust.currentBundleRecord },
                installBackend: { _, _ in
                    Issue.record("backend must not be reached after tampering")
                }
            )
            Issue.record("tampered bundle unexpectedly enforced")
        } catch let error as GitRemoteTrustError {
            // Tampering changes the byte length too, so whichever of the
            // two content checks trips first proves re-verification.
            switch error {
            case .digestMismatch, .byteCountMismatch: break
            default: Issue.record("unexpected trust error: \(error)")
            }
        }
    }

    @Test("missing file after install fails the operation as not-a-regular-file")
    func removedFileFails() throws {
        let trust = GitRemoteTrust()
        let root = try makePrivateRoot("removed")
        defer { try? FileManager.default.removeItem(at: root) }
        let record = try makeRecord(inRoot: root, bytes: twoCertBundleBytes(), bundleID: "gtb-removed")
        _ = try trust.install(record)
        try FileManager.default.removeItem(
            at: root.appendingPathComponent(GitRemoteTrust.bundleFileName)
        )
        #expect(throws: GitRemoteTrustError.bundleNotARegularFile) {
            try GitRemoteTrust.enforceRemoteTrust(
                bindingProvider: { trust.currentBundleRecord },
                installBackend: { _, _ in }
            )
        }
    }
}

@Suite("GitRemoteTrust decision table")
struct GitRemoteTrustEnforcementTests {
    @Test("unbound trust gates remote operations: nothing reaches the backend")
    func unboundFailsClosed() {
        var backendReached = false
        #expect(throws: GitRemoteTrustError.trustUnbound) {
            try GitRemoteTrust.enforceRemoteTrust(
                bindingProvider: { nil },
                installBackend: { _, _ in backendReached = true }
            )
        }
        #expect(!backendReached)
    }

    @Test("a verified bundle is installed into the active runtime exactly once per operation")
    func verifiedThenInstalled() throws {
        let root = try makePrivateRoot("install-once")
        defer { try? FileManager.default.removeItem(at: root) }
        let record = try makeRecord(inRoot: root, bytes: twoCertBundleBytes(), bundleID: "gtb-install")
        var installations: [(String, String)] = []
        try GitRemoteTrust.enforceRemoteTrust(
            bindingProvider: { record },
            installBackend: { received, resolved in
                installations.append((received.bundleID, resolved))
            }
        )
        #expect(installations.count == 1)
        #expect(installations.first?.0 == "gtb-install")
        #expect(installations.first?.1.hasSuffix(GitRemoteTrust.bundleFileName) == true)
    }

    @Test("backend failure propagates typed and keeps the pre-verification done")
    func backendFailurePropagates() throws {
        let root = try makePrivateRoot("backend-fail")
        defer { try? FileManager.default.removeItem(at: root) }
        let record = try makeRecord(inRoot: root, bytes: twoCertBundleBytes(), bundleID: "gtb-backend")
        #expect(throws: GitRemoteTrustError.backendInstallationFailed(reason: "injected failure")) {
            try GitRemoteTrust.enforceRemoteTrust(
                bindingProvider: { record },
                installBackend: { _, _ in
                    throw GitRemoteTrustError.backendInstallationFailed(reason: "injected failure")
                }
            )
        }
    }

    @Test("the real shim against the vendored backend behaves per platform, fail-closed on Apple hosts")
    func realBackendInstall() throws {
        let root = try makePrivateRoot("real-backend")
        defer { try? FileManager.default.removeItem(at: root) }
        let record = try makeRecord(inRoot: root, bytes: twoCertBundleBytes(), bundleID: "gtb-real")
        let resolved = try GitRemoteTrust.verify(record)
        guard git_libgit2_init() >= 0 else { Issue.record("libgit2 init failed"); return }
        defer { _ = git_libgit2_shutdown() }
        #if os(Android)
        try GitRemoteTrust.installCAChain(record: record, resolvedBundlePath: resolved)
        #else
        // Apple SecureTransport overlay: settings.c refuses CA locations.
        // The seam must surface that as a typed failure, never as success.
        do {
            try GitRemoteTrust.installCAChain(record: record, resolvedBundlePath: resolved)
            #expect(Bool(false), "CA-location install unexpectedly succeeded on the Apple backend")
        } catch let error as GitRemoteTrustError {
            guard case .backendInstallationFailed = error else {
                Issue.record("unexpected trust error: \(error)")
                return
            }
        }
        #endif
    }

    @Test("Apple host prepareRemoteOperation passes through (iOS-parity TLS backend); Android would gate")
    func prepareRemoteOperationPlatformBranch() throws {
        let trust = GitRemoteTrust()
        #if os(Android)
        #expect(throws: (any Error).self) { try trust.prepareRemoteOperation() }
        #else
        try trust.prepareRemoteOperation()   // documented no-op passthrough
        #endif
    }

    @Test("the FloeError mapping keeps the unbound case an invalidConfiguration without paths or digests")
    func unboundMapsToTypedConfigurationError() {
        let mapped = GitRemoteTrust.floeError(for: .trustUnbound)
        #expect(mapped == FloeError.invalidConfiguration(
            FloeL10n.l("git.git_remote_trust.network_git_operations_require_the_platform")
        ))
        let revoked = GitRemoteTrust.floeError(for: .digestMismatch(expected: "a", observed: "b"))
        guard case .syncUnavailable(let detail) = revoked else {
            Issue.record("expected syncUnavailable mapping")
            return
        }
        #expect(!detail.contains("/"))   // no path material in the message
    }
}

@Suite("Git remote operation policy")
struct GitRemoteOperationPolicyTests {
    @Test("credential callbacks are scoped exactly to the HTTPS github.com contract")
    func credentialScope() {
        let allowed = [
            "https://github.com/o/r.git",
            "https://github.com/o/r",
            "HTTPS://GitHub.COM/x",
            "https://gist.github.com/x",
        ]
        for url in allowed {
            #expect(GitRemoteOperationPolicy.credentialScopeAllows(url: url), "should allow \(url)")
        }
        let rejected: [String?] = [
            nil, "", "http://github.com/x", "ssh://git@github.com/x",
            "https://evil.example/x", "https://github.com.evil.com/x",
            "https://user:token@github.com/x", "https://tok@github.com/x",
            "https://example.com/github.com", "not a url",
            "https:/github.com",
        ]
        for url in rejected {
            #expect(!GitRemoteOperationPolicy.credentialScopeAllows(url: url), "should reject \(url ?? "nil")")
        }
    }

    @Test("the pinned redirect mode is GIT_REMOTE_REDIRECT_NONE as the vendored libgit2 defines it")
    func pinnedRedirectConstant() {
        // The C shim compiles the constant against the vendored 1.9.2
        // headers; 1 is NONE (0 would mean "unspecified" and let the
        // repository's http.followRedirects widen the policy — see the
        // GitRemoteTrust header).
        #expect(GitRemoteOperationPolicy.pinnedRedirectNoneValue == 1)
    }

    @Test("redirect pinning applies to clone, fetch and push option structs")
    func applyPinnedRedirectsSetsNone() {
        var cloneOptions = git_clone_options()
        _ = git_clone_options_init(&cloneOptions, UInt32(GIT_CLONE_OPTIONS_VERSION))
        #expect(Int(cloneOptions.fetch_opts.follow_redirects.rawValue) == 0)
        GitRemoteOperationPolicy.applyPinnedRedirects(to: &cloneOptions)
        #expect(Int(cloneOptions.fetch_opts.follow_redirects.rawValue) == Int(GitRemoteOperationPolicy.pinnedRedirectNoneValue))

        var fetchOptions = git_fetch_options()
        _ = git_fetch_options_init(&fetchOptions, UInt32(GIT_FETCH_OPTIONS_VERSION))
        #expect(Int(fetchOptions.follow_redirects.rawValue) == 0)
        GitRemoteOperationPolicy.applyPinnedRedirects(to: &fetchOptions)
        #expect(Int(fetchOptions.follow_redirects.rawValue) == Int(GitRemoteOperationPolicy.pinnedRedirectNoneValue))

        var pushOptions = git_push_options()
        _ = git_push_options_init(&pushOptions, UInt32(GIT_PUSH_OPTIONS_VERSION))
        #expect(Int(pushOptions.follow_redirects.rawValue) == 0)
        GitRemoteOperationPolicy.applyPinnedRedirects(to: &pushOptions)
        #expect(Int(pushOptions.follow_redirects.rawValue) == Int(GitRemoteOperationPolicy.pinnedRedirectNoneValue))
    }

    @Test("offline Git stays available without any trust binding (URL validation still first)")
    func offlineAndUnvalidatedRemoteUnaffected() async throws {
        let git = LocalGitService()
        let root = try! makePrivateRoot("offline")
        defer { try? FileManager.default.removeItem(at: root) }
        // No bundle installed anywhere for this process decision: local
        // status must still work.
        let snapshot = try await git.snapshot(at: root)
        #expect(!snapshot.isRepository)

        // A disallowed remote is rejected as before, before any trust or
        // network consideration, with the original typed validation error.
        await #expect(throws: (any Error).self) {
            try await git.clone(from: URL(string: "http://github.com/x/y.git")!, to: root.appendingPathComponent("nope"), token: nil)
        }
    }
}
